def experiment(inputs):
    import random
    seeds = inputs.get('seeds', [42])
    results = []
    for s in seeds:
        random.seed(s)
        val1 = 10.0
        val2 = 10.0
        for _ in range(5):
            val1 += random.uniform(-1.0, 1.0)
            val2 += random.uniform(-1.5, 1.5)
        results.append(abs(val1 - val2) > 0.001)
    return {'measurements': {'value_divergence': results}}
